            // TODO API_TEST_START
            java.io.File dir = new java.io.File(output_dir);
            if (!dir.exists()) {
                dir.mkdirs();
            }

            net.coobird.thumbnailator.name.ConsecutivelyNumberedFilenames filenames = 
                new net.coobird.thumbnailator.name.ConsecutivelyNumberedFilenames(dir, "thumb-%03d.jpg", 5);

            java.util.List<java.io.File> resultFiles = net.coobird.thumbnailator.Thumbnails.of(grid_png, grid_jpeg)
